"""Build a self-contained interactive HTML snapshot from a Luna pilot directory."""
import json, re, sys, time
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT))
from sepdesign.tasks import Economics
from scripts.price_luna_pilot import estimate
run=Path(sys.argv[1]).resolve()
config=json.loads((run/'config.json').read_text())
rows=[json.loads(s) for s in (run/'trajectory.jsonl').read_text().splitlines() if s.strip()]
econ=Economics(json.loads((ROOT/'tasks/hc12_dev_000.json').read_text()))
norm=econ.reward_norm
usage=[]
for p in sorted(run.glob('response-*.json')):
 r=json.loads(p.read_text()); u=r['usage']; usage.append(dict(turn=int(p.stem.split('-')[1]),input=u['input_tokens'],output=u['output_tokens'],cached=u.get('input_tokens_details',{}).get('cached_tokens',0),usd=estimate(u, r['model'])))
points=[dict(solves=0,minutes=0,usd=0,best=0,current=0,valid=True)]
for row in rows:
 f=row['feedback']; points.append(dict(turn=row['turn']+1,solves=f['solves_used'],minutes=row['elapsed_s']/60,usd=sum(u['usd'] for u in usage if u['turn']<=row['turn']),best=f['best_reward']*norm/1e6,current=f['reward']*norm/1e6,valid=f['valid']))
last=rows[-1]['feedback']; bestrow=max(rows,key=lambda r:r['feedback']['best_reward'])
bestrow=next((r for r in rows if r['feedback']['valid'] and r['feedback']['reward']==last['best_reward']),bestrow)
match=re.search(r'revenue \$([\d.]+)M/yr \| column cost \$([\d.]+)M/yr',bestrow['feedback']['feedback'])
first=next((p for p in points if p['best']>0),None)
data=dict(ceiling=econ.max_total_revenue/1e6,config=config,points=points,usage=usage,rows=rows,status='Complete' if (run/'summary.json').exists() else 'In progress — snapshot',updated=time.strftime('%Y-%m-%d %H:%M:%S %Z'),first=first,best_design=bestrow['feedback']['best_design'],stats=last['stats'],revenue=float(match[1]) if match else None,cost=float(match[2]) if match else None)
html='''<!doctype html><html><head><meta charset="utf-8"><title>Luna • Engineering pilot</title><style>
:root{color-scheme:light;font-family:Inter,system-ui,sans-serif;background:#f5f7fa;color:#192a3d}*{box-sizing:border-box}body{max-width:1440px;margin:auto;padding:36px}header{display:flex;justify-content:space-between;align-items:center}h1{font-size:32px;margin:8px 0}h2{font-size:17px;margin:0 0 12px}.eyebrow{color:#157453;text-transform:uppercase;letter-spacing:2px;font-size:12px}.muted,small{color:#53677f}.badge{border:1px solid #a8cdbc;border-radius:20px;color:#146847;padding:8px 14px;font-size:13px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:26px 0}.card,.panel{background:#ffffff;border:1px solid #d9e1eb;border-radius:14px;padding:20px}.value{font-size:29px;font-weight:650;margin:10px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.chart{height:260px;width:100%}svg{width:100%;height:100%;overflow:visible}svg text{fill:#53677f;font-size:11px}.note{background:#eaf3f8;border-left:3px solid #25876a;padding:14px 18px;color:#364d64;margin:22px 0;font-size:14px;line-height:1.6}table{width:100%;border-collapse:collapse;font-size:13px}td,th{text-align:left;padding:11px 8px;border-bottom:1px solid #dce3eb}th{color:#53677f;font-weight:500}.wide{grid-column:1/-1}button{background:#264963;color:#eef6ff;border:0;padding:9px 14px;border-radius:7px;cursor:pointer}pre{white-space:pre-wrap;line-height:1.6;color:#344c65;font-size:12px}.good{color:#16704f}.bad{color:#b3293e}details{margin-top:15px}summary{cursor:pointer;color:#96b9db}.tip{position:fixed;display:none;pointer-events:none;background:#ffffff;border:1px solid #7da9c1;padding:10px;border-radius:7px;font-size:12px;z-index:5}@media(max-width:850px){.cards,.grid{grid-template-columns:1fr 1fr}body{padding:20px}.panel{grid-column:1/-1}}a{color:#1a66a3}
</style></head><body><header><div><div class="eyebrow">Iterate / single agent pilot</div><h1>Can Luna design a profitable separation plant?</h1><div class="muted">HC12 · GPT-6 Luna · 50 simulator evaluations · low reasoning effort</div></div><span class="badge" id="status"></span></header><div id="cards" class="cards"></div><div class="note" id="note"></div><div class="grid"><section class="panel"><h2>Quality versus simulator budget</h2><small>Best valid objective, $M/year · faint dots show submitted designs</small><div id="budget" class="chart"></div></section><section class="panel"><h2>Quality versus elapsed time</h2><small>Includes model calls and Azure command delivery</small><div id="time" class="chart"></div></section><section class="panel"><h2>Quality versus agent expenditure</h2><small>Estimated model USD, including cache reads and writes; excludes VM</small><div id="spend" class="chart"></div></section><section class="panel"><h2>Where the time goes</h2><small>Measured evaluation time versus command transport overhead</small><div id="timing" class="chart"></div></section><section class="panel"><h2>Best valid plant economics</h2><div id="economics"></div><small>Revenue and cost rounded to $0.1M in the recorded feedback. Net objective calculated from the full-precision reward.</small></section><section class="panel"><h2>Run measurements</h2><table id="metrics"></table></section><section class="panel wide"><h2>Attempt history</h2><small>One submission may consume multiple column evaluations. Hover on plotted points for values.</small><table id="attempts"></table></section><section class="panel wide"><h2>Scope and missing evidence</h2><p class="muted">This is one single-agent plumbing pilot, not evidence that single agents beat swarms. No 3-agent or 5-agent results exist in this report. No error bars or statistical significance are implied.</p><p class="muted">Physical validity uses the provisional material-balance checker. Energy closure and economic calibration remain unverified. Exact product purity/recovery, cache-hit count and raw best-design evidence are not available in this local snapshot; rounded compositions remain visible in the attempt details. Failure rate counts backend evaluation failures. Automatic solver retries are disabled.</p><p class="muted">This is a generated snapshot, not a live connection. Rebuild the HTML to include later results. Model pricing: <a href="https://developers.openai.com/api/docs/pricing">OpenAI standard API rates</a>, checked November 14, 2026. Estimates are not invoices.</p><details><summary>Configuration and best design</summary><pre id="config"></pre></details><small id="footer"></small></section></div><div class="tip" id="tip"></div><script>
const D=DATA_PLACEHOLDER; const $=id=>document.getElementById(id);const last=D.points.at(-1), usd=D.usage.reduce((s,u)=>s+u.usd,0);const fmt=(x,n=2)=>Number(x).toLocaleString(undefined,{maximumFractionDigits:n});
$('status').textContent=D.status;
$('cards').innerHTML=[['Best valid objective','$'+fmt(last.best)+'M/yr','Revenue minus annualized column cost'],['Simulator budget',last.solves+' / 50',D.rows.length+' submitted designs'],['Model expenditure','$'+usd.toFixed(5),D.usage.length+' completed model requests'],['First positive design',D.first?D.first.solves+' solves':'Not yet',D.first?fmt(D.first.minutes)+' minutes elapsed':'Empty baseline remains best']].map(a=>`<div class="card"><small>${a[0]}</small><div class="value">${a[1]}</div><small>${a[2]}</small></div>`).join('');
$('note').textContent='This is one pilot run, not a comparison of agent architectures. The primary objective is the best physically valid annual economic value found so far. The empty plant is a valid $0 baseline. The dashed ceiling assumes perfect recovery of every component as a pure product with zero column cost; it is a hypothetical upper bound, not a demonstrated feasible design. Azure transport time is substantial and must not be used as a swarm speed comparison.';
const ns='http://www.w3.org/2000/svg';function el(n,a,text){let e=document.createElementNS(ns,n);for(let k in a)e.setAttribute(k,a[k]);if(text!==undefined)e.textContent=text;return e}
function chart(id,key,label){let s=el('svg',{viewBox:'0 0 600 260'}), pts=D.points, xmax=Math.max(...pts.map(p=>p[key]),.001),ymin=Math.min(0,...pts.map(p=>p.current)), ymax=D.ceiling*1.10;let x=v=>60+v/xmax*515,y=v=>215-(v-ymin)/(ymax-ymin)*185;
for(let i=0;i<5;i++){let v=ymin+(ymax-ymin)*i/4;s.append(el('line',{x1:60,x2:575,y1:y(v),y2:y(v),stroke:'#dce3eb'}));s.append(el('text',{x:53,y:y(v)+4,'text-anchor':'end'},fmt(v,1)));let xv=xmax*i/4;s.append(el('text',{x:x(xv),y:236,'text-anchor':'middle'},key==='usd'?xv.toFixed(4):fmt(xv,1)))}
s.append(el('line',{x1:60,x2:575,y1:y(D.ceiling),y2:y(D.ceiling),stroke:'#b17922','stroke-width':2,'stroke-dasharray':'7 5'}));s.append(el('text',{x:570,y:y(D.ceiling)-8,'text-anchor':'end'},'Ideal ceiling: $'+fmt(D.ceiling,1)+'M/yr'));s.append(el('text',{x:320,y:255,'text-anchor':'middle'},label));let path='M'+x(0)+','+y(0);for(let p of pts.slice(1))path+=' H'+x(p[key])+' V'+y(p.best);s.append(el('path',{d:path,fill:'none',stroke:'#16825f','stroke-width':3}));for(let p of pts){s.append(el('circle',{cx:x(p[key]),cy:y(p.current),r:3,fill:p.valid?'#6e93b8':'#bd5062',opacity:.7}));let c=el('circle',{cx:x(p[key]),cy:y(p.best),r:5,fill:'#16825f'});c.onmousemove=e=>{let t=$('tip');t.style.display='block';t.style.left=e.clientX+12+'px';t.style.top=e.clientY+12+'px';t.textContent=`${p.solves} solves · ${fmt(p.minutes)} min · $${p.usd.toFixed(5)} model spend · best $${fmt(p.best)}M/yr`};c.onmouseleave=()=>$('tip').style.display='none';s.append(c)}$(id).append(s)}
chart('budget','solves','Distinct column evaluations');chart('time','minutes','Elapsed minutes');chart('spend','usd','Cumulative estimated model USD');
const sim=D.rows.reduce((s,r)=>s+r.feedback.evaluation_s,0),transport=D.rows.reduce((s,r)=>s+r.transport_wall_s-r.feedback.evaluation_s,0),model=D.points.at(-1).minutes*60-sim-transport;let timing=[['Simulator evaluation',sim,'#16825f'],['Azure transport overhead',transport,'#477fae'],['Model calls + local overhead',Math.max(0,model),'#8c6db6']];$('timing').innerHTML=timing.map(a=>`<div style="margin:24px 0"><small>${a[0]} · ${fmt(a[1])}s</small><div style="height:16px;background:#e5ecf3;margin-top:7px;border-radius:4px"><div style="height:100%;width:${Math.max(0.5,100*a[1]/Math.max(...timing.map(t=>t[1])))}%;background:${a[2]};border-radius:4px"></div></div></div>`).join('');
$('economics').innerHTML=[['Revenue',D.revenue],['Annualized column cost',D.cost],['Net annual objective',last.best],['Hypothetical ceiling',D.ceiling]].map(a=>`<div style="display:flex;justify-content:space-between;padding:16px 0;border-bottom:1px solid #dce3eb"><span>${a[0]}</span><strong>$${fmt(a[1])}M/yr</strong></div>`).join('');
const valid=D.rows.filter(r=>r.feedback.valid).length;let metrics=[['Valid submissions',valid+' / '+D.rows.length],['Backend failures',(D.stats.failed||0)+' / '+D.stats.solves],['Median column solve',fmt(D.stats.median_s,3)+'s'],['Mean column solve',fmt(D.stats.mean_s,3)+'s'],['Input tokens',fmt(D.usage.reduce((s,u)=>s+u.input,0),0)],['Output tokens (includes reasoning)',fmt(D.usage.reduce((s,u)=>s+u.output,0),0)],['Cached-input tokens (subset)',fmt(D.usage.reduce((s,u)=>s+u.cached,0),0)],['Best plant columns',Object.keys(D.best_design).length],['Fraction of hypothetical ceiling',fmt(100*last.best/D.ceiling)+'%'],['Gap to hypothetical ceiling','$'+fmt(D.ceiling-last.best)+'M/yr'],['Budget comparison','Single agent only']];$('metrics').innerHTML=metrics.map(a=>`<tr><td>${a[0]}</td><td>${a[1]}</td></tr>`).join('');
$('attempts').innerHTML='<tr><th>Attempt</th><th>Solves used</th><th>Valid</th><th>Candidate $M/yr</th><th>Best $M/yr</th><th>Agent intent / feedback</th></tr>'+D.rows.map((r,i)=>{let p=D.points[i+1];return `<tr><td>${i+1}</td><td>${p.solves}</td><td class="${p.valid?'good':'bad'}">${p.valid?'Yes':'No'}</td><td>${fmt(p.current)}</td><td>${fmt(p.best)}</td><td><details><summary id="reason-${i}"></summary><pre id="feedback-${i}"></pre></details></td></tr>`}).join('');D.rows.forEach((r,i)=>{$('reason-'+i).textContent=r.proposal.reason;$('feedback-'+i).textContent=r.feedback.feedback});$('config').textContent=JSON.stringify({config:D.config,best_design:D.best_design},null,2);$('footer').textContent=D.config.run_id+' · generated '+D.updated;
</script></body></html>'''
assets=ROOT/'scripts/report_assets'
html=html.replace('<div class="grid">', (assets/'flowsheet.html').read_text()+'<div class="grid">', 1)
html=html.replace('</script></body>', (assets/'flowsheet.js').read_text()+'</script></body>')
html=html.replace('Luna • Engineering pilot',config['model']+' • Engineering pilot').replace('Can Luna design a profitable separation plant?', 'Can '+config['model']+' design a profitable separation plant?').replace('GPT-6 Luna ·',config['model']+' ·')
html=html.replace('DATA_PLACEHOLDER',json.dumps(data).replace('<','\\u003c'))
output=run/'report.html';output.write_text(html);print(output)
